def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    def tokenize(s: str) -> list[tuple[str, object]]:
        tokens: list[tuple[str, object]] = []
        i = 0
        n = len(s)
        while i < n:
            ch = s[i]
            if ch.isspace():
                i += 1
            elif "0" <= ch <= "9":
                j = i + 1
                while j < n and "0" <= s[j] <= "9":
                    j += 1
                tokens.append(("INT", int(s[i:j])))
                i = j
            elif "A" <= ch <= "Z":
                j = i + 1
                while j < n and "A" <= s[j] <= "Z":
                    j += 1
                if j == i + 1 and j < n and "0" <= s[j] <= "9":
                    k = j + 1
                    while k < n and "0" <= s[k] <= "9":
                        k += 1
                    idx = (int(s[j:k]) - 1) * 26 + (ord(ch) - 65)
                    tokens.append(("CELL", idx))
                    i = k
                else:
                    tokens.append(("FUNC", s[i:j]))
                    i = j
            elif ch == "<":
                if i + 1 < n and s[i + 1] in (">", "="):
                    tokens.append(("OP", s[i : i + 2]))
                    i += 2
                else:
                    tokens.append(("OP", "<"))
                    i += 1
            elif ch == ">":
                if i + 1 < n and s[i + 1] == "=":
                    tokens.append(("OP", ">="))
                    i += 2
                else:
                    tokens.append(("OP", ">"))
                    i += 1
            elif ch == "=":
                tokens.append(("OP", "="))
                i += 1
            else:
                tokens.append((ch, ch))
                i += 1
        tokens.append(("EOF", None))
        return tokens

    prec = {"+": 1, "-": 1, "*": 2, "/": 2, "neg": 3}

    def apply_op(values: list[tuple], op: str) -> None:
        if op == "neg":
            v = values.pop()
            values.append(("neg", v))
        else:
            r = values.pop()
            l = values.pop()
            values.append(("bin", op, l, r))

    def parse(s: str) -> tuple:
        tokens = tokenize(s)
        pos = 0
        ctx_stack: list[dict] = [
            {"kind": "root", "values": [], "ops": [], "expect": True, "paren": 0}
        ]
        while True:
            ctx = ctx_stack[-1]
            tok_type, tok_val = tokens[pos]
            if ctx["expect"]:
                if tok_type == "-":
                    ctx["ops"].append("neg")
                    pos += 1
                elif tok_type == "(":
                    ctx["ops"].append("(")
                    ctx["paren"] += 1
                    pos += 1
                elif tok_type == "INT":
                    ctx["values"].append(("num", tok_val))
                    ctx["expect"] = False
                    pos += 1
                elif tok_type == "CELL":
                    if (
                        ctx["kind"] == "agg"
                        and ctx["paren"] == 0
                        and not ctx["ops"]
                        and not ctx["values"]
                        and tokens[pos + 1][0] == ":"
                    ):
                        idx1 = tok_val
                        idx2 = tokens[pos + 2][1]
                        pos += 3
                        r1, c1 = divmod(idx1, 26)
                        r2, c2 = divmod(idx2, 26)
                        ctx["args"].append(
                            (
                                "range",
                                r1 if r1 <= r2 else r2,
                                r2 if r1 <= r2 else r1,
                                c1 if c1 <= c2 else c2,
                                c2 if c1 <= c2 else c1,
                            )
                        )
                        nxt = tokens[pos][0]
                        pos += 1
                        if nxt != ",":
                            ctx_stack.pop()
                            node = ("agg", ctx["func"], ctx["args"])
                            parent = ctx_stack[-1]
                            parent["values"].append(node)
                            parent["expect"] = False
                    else:
                        ctx["values"].append(("cell", tok_val))
                        ctx["expect"] = False
                        pos += 1
                elif tok_type == "FUNC":
                    pos += 2
                    if tok_val == "IF":
                        ctx_stack.append(
                            {
                                "kind": "if_left",
                                "op": None,
                                "left": None,
                                "right": None,
                                "then": None,
                                "values": [],
                                "ops": [],
                                "expect": True,
                                "paren": 0,
                            }
                        )
                    else:
                        ctx_stack.append(
                            {
                                "kind": "agg",
                                "func": tok_val,
                                "args": [],
                                "values": [],
                                "ops": [],
                                "expect": True,
                                "paren": 0,
                            }
                        )
            else:
                if tok_type in ("+", "-", "*", "/"):
                    p = prec[tok_type]
                    ops = ctx["ops"]
                    vals = ctx["values"]
                    while ops and ops[-1] != "(" and prec[ops[-1]] >= p:
                        apply_op(vals, ops.pop())
                    ops.append(tok_type)
                    ctx["expect"] = True
                    pos += 1
                elif tok_type == ")" and ctx["paren"] > 0:
                    ops = ctx["ops"]
                    vals = ctx["values"]
                    while ops[-1] != "(":
                        apply_op(vals, ops.pop())
                    ops.pop()
                    ctx["paren"] -= 1
                    pos += 1
                else:
                    ops = ctx["ops"]
                    vals = ctx["values"]
                    while ops:
                        apply_op(vals, ops.pop())
                    expr = vals[0]
                    pos += 1
                    kind = ctx["kind"]
                    if kind == "root":
                        return expr
                    elif kind == "agg":
                        ctx["args"].append(expr)
                        if tok_type == ",":
                            ctx["values"] = []
                            ctx["ops"] = []
                            ctx["expect"] = True
                        else:
                            ctx_stack.pop()
                            node = ("agg", ctx["func"], ctx["args"])
                            parent = ctx_stack[-1]
                            parent["values"].append(node)
                            parent["expect"] = False
                    elif kind == "if_left":
                        ctx["left"] = expr
                        ctx["op"] = tok_val
                        ctx["kind"] = "if_right"
                        ctx["values"] = []
                        ctx["ops"] = []
                        ctx["expect"] = True
                    elif kind == "if_right":
                        ctx["right"] = expr
                        ctx["kind"] = "if_then"
                        ctx["values"] = []
                        ctx["ops"] = []
                        ctx["expect"] = True
                    elif kind == "if_then":
                        ctx["then"] = expr
                        ctx["kind"] = "if_else"
                        ctx["values"] = []
                        ctx["ops"] = []
                        ctx["expect"] = True
                    else:
                        ctx_stack.pop()
                        node = (
                            "if",
                            ctx["op"],
                            ctx["left"],
                            ctx["right"],
                            ctx["then"],
                            expr,
                        )
                        parent = ctx_stack[-1]
                        parent["values"].append(node)
                        parent["expect"] = False

    present = [False] * 2574
    state = [0] * 2574
    vals: list[int | str] = [0] * 2574
    asts: list[tuple | None] = [None] * 2574
    cell_indices: list[tuple[str, int]] = []

    for name, content in cells.items():
        idx = (int(name[1:]) - 1) * 26 + (ord(name[0]) - 65)
        cell_indices.append((name, idx))
        present[idx] = True
        s = content.strip()
        if s.startswith("="):
            asts[idx] = parse(s[1:])
        else:
            vals[idx] = int(s)
            state[idx] = 2

    for _, start_idx in cell_indices:
        if state[start_idx] != 0:
            continue
        state[start_idx] = 1
        stack: list = [("finish_cell", start_idx), ("eval", asts[start_idx])]
        res: int | str = 0
        while stack:
            top = stack[-1]
            tag = top[0]
            if tag == "eval":
                stack.pop()
                node = top[1]
                ntype = node[0]
                if ntype == "num":
                    res = node[1]
                elif ntype == "cell":
                    idx = node[1]
                    if not present[idx]:
                        res = 0
                    elif state[idx] == 2:
                        res = vals[idx]
                    elif state[idx] == 1:
                        res = "#CYCLE!"
                    else:
                        state[idx] = 1
                        stack.append(("finish_cell", idx))
                        stack.append(("eval", asts[idx]))
                elif ntype == "neg":
                    stack.append(("apply_neg",))
                    stack.append(("eval", node[1]))
                elif ntype == "bin":
                    stack.append(("bin_left", node[1], node[3]))
                    stack.append(("eval", node[2]))
                elif ntype == "if":
                    stack.append(("if_left", node[1], node[3], node[4], node[5]))
                    stack.append(("eval", node[2]))
                else:
                    fname = node[1]
                    stack.append(
                        [
                            "agg",
                            fname,
                            node[2],
                            0,
                            False,
                            0,
                            0,
                            0,
                            0,
                            0,
                            0 if fname == "SUM" else None,
                            False,
                        ]
                    )
            elif tag == "finish_cell":
                stack.pop()
                idx = top[1]
                vals[idx] = res
                state[idx] = 2
            elif tag == "apply_neg":
                stack.pop()
                if not isinstance(res, str):
                    res = -res
            elif tag == "bin_left":
                stack.pop()
                if not isinstance(res, str):
                    stack.append(("bin_right", top[1], res))
                    stack.append(("eval", top[2]))
            elif tag == "bin_right":
                stack.pop()
                if not isinstance(res, str):
                    op = top[1]
                    lv = top[2]
                    if op == "+":
                        res = lv + res
                    elif op == "-":
                        res = lv - res
                    elif op == "*":
                        res = lv * res
                    else:
                        if res == 0:
                            res = "#DIV/0!"
                        else:
                            q = abs(lv) // abs(res)
                            res = -q if (lv < 0) != (res < 0) else q
            elif tag == "if_left":
                stack.pop()
                if not isinstance(res, str):
                    stack.append(("if_right", top[1], res, top[3], top[4]))
                    stack.append(("eval", top[2]))
            elif tag == "if_right":
                stack.pop()
                if not isinstance(res, str):
                    op = top[1]
                    lv = top[2]
                    if op == "=":
                        cond = lv == res
                    elif op == "<>":
                        cond = lv != res
                    elif op == "<":
                        cond = lv < res
                    elif op == "<=":
                        cond = lv <= res
                    elif op == ">":
                        cond = lv > res
                    else:
                        cond = lv >= res
                    stack.append(("eval", top[3] if cond else top[4]))
            else:
                fname = top[1]
                if top[11]:
                    if isinstance(res, str):
                        stack.pop()
                        continue
                    acc = top[10]
                    if fname == "SUM":
                        top[10] = acc + res
                    elif fname == "MIN":
                        if acc is None or res < acc:
                            top[10] = res
                    else:
                        if acc is None or res > acc:
                            top[10] = res
                    top[11] = False

                if top[4]:
                    r = top[5]
                    c = top[6]
                    c_min = top[7]
                    c_max = top[8]
                    r_max = top[9]
                    acc = top[10]
                    paused = False
                    errored = False
                    while r <= r_max:
                        row_base = r * 26
                        while c <= c_max:
                            idx = row_base + c
                            c += 1
                            if not present[idx]:
                                continue
                            st = state[idx]
                            if st == 2:
                                v = vals[idx]
                                if isinstance(v, str):
                                    res = v
                                    stack.pop()
                                    errored = True
                                    break
                                if fname == "SUM":
                                    acc += v
                                elif fname == "MIN":
                                    if acc is None or v < acc:
                                        acc = v
                                else:
                                    if acc is None or v > acc:
                                        acc = v
                            elif st == 1:
                                res = "#CYCLE!"
                                stack.pop()
                                errored = True
                                break
                            else:
                                if c > c_max:
                                    c = c_min
                                    r += 1
                                top[5] = r
                                top[6] = c
                                top[10] = acc
                                top[11] = True
                                state[idx] = 1
                                stack.append(("finish_cell", idx))
                                stack.append(("eval", asts[idx]))
                                paused = True
                                break
                        if errored or paused:
                            break
                        c = c_min
                        r += 1
                    if errored or paused:
                        continue
                    top[10] = acc
                    top[4] = False
                    top[3] += 1

                args = top[2]
                arg_idx = top[3]
                if arg_idx == len(args):
                    acc = top[10]
                    res = 0 if acc is None else acc
                    stack.pop()
                else:
                    arg = args[arg_idx]
                    if arg[0] == "range":
                        top[4] = True
                        top[5] = arg[1]
                        top[6] = arg[3]
                        top[7] = arg[3]
                        top[8] = arg[4]
                        top[9] = arg[2]
                    else:
                        top[3] = arg_idx + 1
                        top[11] = True
                        stack.append(("eval", arg))

    return {name: vals[idx] for name, idx in cell_indices}
